    get(): ExpoGoConfig | null {
      return PARSED_MANIFEST as any;
    },
    enumerable: true,
  },
  easConfig: {
    get(): EASConfig | null {
      return PARSED_MANIFEST as any;
    },
    enumerable: true,
  },
});

export default constants as Constants;

